```
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/time.h>
#include <stdlib.h>
#include <time.h>
#include <sys/libc.h>

#define DATA_MAX_SIZE 1024
#define TOTAL_DATA 500000

void enviarEstoque(int socket, int porta, const char *nomeDoServidor, int tamanhoDoEstoque) {
    char buffer[DATA_MAX_SIZE];
    socket.sendto(buffer, tamanhoDoEstoque, socket, porta, (struct sockaddr *)&nomeDoServidor, sizeof(nomeDoServidor));
}

int receberEstoque(int socket, int tamanhoDoEstoque) {
    char buffer[tamanhoDoEstoque];
    int tamanhoDeBuffer = recv(socket, buffer, tamanhoDoEstoque, 0);
    if (tamanhoDeBuffer < 0) {
        perror("Erro ao receber dados");
        return -1;
    }
    buffer[tamanhoDeBuffer] = 0;
    return buffer[tamanhoDeBuffer + 1];
}

int main() {
    int socket, porta, tamanhoDoEstoque;
    char nomeDoServidor[20];
    int op = 1;

    socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket < 0) {
        perror("Erro ao criar socket");
        return -1;
    }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);
    serv_addr.sin_addr.s_addr = INADDR_ANY;

    while (op > 0) {
        op = receberEstoque(socket, tamanhoDoEstoque);
        if (op == -1) {
            break;
        }

        // Receber dados do servidor
        char buffer[tamanhoDoEstoque];
        tamanhoDeBuffer = recv(socket, buffer, tamanhoDoEstoque, 0);
        if (tamanhoDeBuffer < 0) {
            perror("Erro ao receber dados do servidor");
            break;
        }
        buffer[tamanhoDeBuffer] = 0;

        // Processar dados
        if (strcmp(buffer, "nada") == 0) {
            // Fazer algo aqui...
        } else {
            // Deixar o código como é
        }

        // Enviar dados de volta
        enviarEstoque(socket, porta, nomeDoServidor, tamanhoDoEstoque);
    }

    return 0;
}
```

